using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using StockWise.Data; using StockWise.ViewModels;
namespace StockWise.Controllers;
[Authorize]
public class HomeController : Controller { private readonly AppDbContext _db; public HomeController(AppDbContext db)=>_db=db; public async Task<IActionResult> Index(){var now=DateTime.UtcNow; var today=now.Date; var monthStart=new DateTime(now.Year,now.Month,1); var vm=new DashboardViewModel{ProductCount=await _db.Products.CountAsync(),CategoryCount=await _db.Categories.CountAsync(),LowStockCount=await _db.Products.CountAsync(p=>p.Quantity<=p.ReorderLevel),TotalSales=await _db.Sales.SumAsync(s=>(decimal?)s.TotalAmount)??0m,InvoiceCount=await _db.Sales.CountAsync(),ThisMonthRevenue=await _db.Sales.Where(s=>s.CreatedAtUtc>=monthStart).SumAsync(s=>(decimal?)s.TotalAmount)??0m,ThisMonthInvoices=await _db.Sales.CountAsync(s=>s.CreatedAtUtc>=monthStart),LowStockProducts=await _db.Products.Include(p=>p.Category).Where(p=>p.Quantity<=p.ReorderLevel).OrderBy(p=>p.Quantity).Take(8).ToListAsync(),RecentSales=await _db.Sales.OrderByDescending(s=>s.CreatedAtUtc).Take(5).ToListAsync()}; var ws=today.AddDays(-6); var w=await _db.Sales.Where(s=>s.CreatedAtUtc>=ws&&s.CreatedAtUtc<today.AddDays(1)).ToListAsync(); for(var d=ws;d<=today;d=d.AddDays(1)){vm.WeeklyLabels.Add(d.ToString("ddd"));vm.WeeklyRevenue.Add(w.Where(x=>x.CreatedAtUtc.Date==d).Sum(x=>x.TotalAmount));} var fs=monthStart.AddMonths(-5); var m=await _db.Sales.Where(s=>s.CreatedAtUtc>=fs&&s.CreatedAtUtc<monthStart.AddMonths(1)).ToListAsync();for(int i=0;i<6;i++){var dt=fs.AddMonths(i);vm.MonthlyLabels.Add(dt.ToString("MMM yy"));vm.MonthlyRevenue.Add(m.Where(x=>x.CreatedAtUtc.Year==dt.Year&&x.CreatedAtUtc.Month==dt.Month).Sum(x=>x.TotalAmount));} vm.TopSellingProducts=await _db.SaleItems.Include(i=>i.Product).GroupBy(i=>i.Product!.Name).Select(g=>new TopSellingProductViewModel{ProductName=g.Key,UnitsSold=g.Sum(i=>i.Quantity),Revenue=g.Sum(i=>i.LineTotal)}).OrderByDescending(x=>x.UnitsSold).Take(5).ToListAsync();return View(vm);} public IActionResult Error()=>View(); }
